const e = $json;
const userText = (e.userText || e.message?.text || '').toString().trim();
const locale = (e.l10n?.detectedLocale || e.state?.locale || 'fr');
const cartItems = (e.cart?.items || []).map(i => i.name).join(', ');
const stage = (e.state?.stage || 'START');

const systemPrompt = `You are RestoBot, a restaurant ordering assistant for an Algerian restaurant.
You classify customer messages into exactly ONE intent.
Valid intents: GREET, VIEW_MENU, ADD_ITEM, REMOVE_ITEM, VIEW_CART, CHECKOUT, DELIVERY, SUPPORT, FAQ, LANG_SWITCH, UNKNOWN.
Respond ONLY with a JSON object: {"intent": "...", "confidence": 0.0-1.0, "entities": {}}
Do NOT include any other text.`;

const userPrompt = `Customer message (locale: ${locale}, stage: ${stage}, cart: [${cartItems}]):
"${userText.substring(0, 500)}"`;

return [{ json: { ...e, _llm: { systemPrompt, userPrompt, userText } } }];

const e = $json;
const fallback = { intent: 'UNKNOWN', confidence: 0, entities: {}, llm_used: false };

try {
  const body = e.body || e.data || e;
  const content = (body?.message?.content || '').toString().trim();
  if (!content) return [{ json: { ...e, llmResult: { ...fallback, reason: 'empty_response' } } }];

  // Try to parse JSON from the LLM response
  const jsonMatch = content.match(/\{[^}]+\}/);
  if (!jsonMatch) return [{ json: { ...e, llmResult: { ...fallback, reason: 'no_json_in_response' } } }];

  const parsed = JSON.parse(jsonMatch[0]);
  const validIntents = ['GREET','VIEW_MENU','ADD_ITEM','REMOVE_ITEM','VIEW_CART','CHECKOUT','DELIVERY','SUPPORT','FAQ','LANG_SWITCH','UNKNOWN'];
  const intent = validIntents.includes(parsed.intent) ? parsed.intent : 'UNKNOWN';
  const confidence = Math.min(1, Math.max(0, Number(parsed.confidence) || 0));

  return [{ json: { ...e, llmResult: { intent, confidence, entities: parsed.entities || {}, llm_used: true } } }];
} catch (err) {
  return [{ json: { ...e, llmResult: { ...fallback, reason: 'parse_error', error: err.message } } }];
}
